// Build follow-up drafting prompt — do NOT repeat the original message
const lead = $input.first().json;
const daysSinceSent = Math.floor((Date.now() - new Date(lead.sent_at).getTime()) / 86400000);

const toneMap = {
  IN: 'Casual, warm, Hinglish-friendly where natural.',
  AE: 'Professional English, polite and direct.',
  QA: 'Professional English, polite and direct.',
  SA: 'Professional English, respectful and relationship-focused.',
  SG: 'Professional English, concise and efficient.'
};
const tone = toneMap[lead.country] || 'Professional English.';

const systemPrompt = `Write a gentle follow-up WhatsApp message for a business owner who has not replied to an initial outreach message sent ${daysSinceSent} days ago.

Rules:
- Under 300 characters.
- Do NOT repeat or paraphrase the original message.
- Do NOT say "following up" or "just checking in" explicitly — keep it light and different.
- Tone: ${tone}
- No emojis. End with a question or an easy invitation to reply.
- This is follow-up #${(lead.follow_up_count || 0) + 1} — adjust lightness/brevity accordingly.

Output ONLY the follow-up message text. No quotes, no preamble.`;

const userContent = `Business: ${lead.business_name} (${lead.category}, ${lead.region})
Original pain point: ${lead.pain_point}
Original angle: ${lead.angle}`;

return [{ json: { ...lead, days_since_sent: daysSinceSent, fu_system_prompt: systemPrompt, fu_user_content: userContent } }];

const response = $input.first().json;
const fuDraft = (response.choices?.[0]?.message?.content || '').trim();
const prev = $('build-followup-prompt').first().json;

// Build wa.me deep link for the follow-up
let waDeepLink = null;
if (prev.phone_normalized) {
  const numericPhone = prev.phone_normalized.replace('+', '');
  waDeepLink = `https://wa.me/${numericPhone}?text=${encodeURIComponent(fuDraft)}`;
}

return [{ json: { ...prev, fu_draft: fuDraft, fu_deep_link: waDeepLink } }];

// Format hot lead notification message
const hotLeads = $input.all().map(item => item.json);
const lines = hotLeads.map(l =>
  `🔥 *${l.business_name}* (${l.category}, ${l.country})
📱 ${l.phone_normalized || 'No phone'}
🔗 ${l.whatsapp_deep_link || 'No WA link'}`
).join('

');

return [{ json: { notification_text: `🚨 *VoxAI Hot Leads Alert*

${lines}

Reply now while intent is high!` } }];
